/* C API of the Rust port of `base64.c`, generated by everything-rust. */
#ifndef BASE64_RS_H
#define BASE64_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

int av_base64_decode(uint8_t *out, const char *in_str, int out_size);
char *av_base64_encode(char *out, int out_size, const uint8_t *in, int in_size);

/* The same functions under `everything_rust_` names, for shadow runs. */
int everything_rust_av_base64_decode(uint8_t *out, const char *in_str, int out_size);
char *everything_rust_av_base64_encode(char *out, int out_size, const uint8_t *in, int in_size);

#endif /* BASE64_RS_H */
